module TopModule (
    input  clk,
    input  a,
    input  b,
    output q,
    output reg state
);

    wire next_state;

    assign next_state = state ? (a | b) : (a & b);
    assign q = state ? ~(a ^ b) : (a ^ b);

    always_ff @(posedge clk) begin
        state <= next_state;
    end

endmodule

